{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table vahdam_db.maplemonk.vahdam_blinkit_pnl_unified as ( with prod_map as ( select trim(replace(blinkit,\'\"\',\'\')) as item_id, any_value(brand) as brand, any_value(trim(\"Common SKU ID\")) as common_sku_id, any_value(\"Common SKU Description\") as common_sku_description, any_value(category) as category, any_value(\"Sub-category\") as sub_category from vahdam_db.maplemonk.vahdam_fy27_inputs_product_mapping where blinkit is not null and trim(replace(blinkit,\'\"\',\'\')) not in (\'\',\'-\') group by 1 ), cogs_sheet as ( select trim(material) as common_sku_id, avg(try_to_decimal(replace(cogs,\',\',\'\'),30,5)) as cogs_per_unit_inr from vahdam_db.maplemonk.vahdam_fy27_inputs_cogs_sheet where material is not null and try_to_decimal(replace(cogs,\',\',\'\'),30,5) > 0 group by 1 ), po_price as ( select item_id, lr from ( select trim(item_id) item_id, try_to_decimal(landing_rate,30,5) lr, row_number() over (partition by trim(item_id) order by try_to_date(left(order_date,10)) desc nulls last) rn from vahdam_db.maplemonk.blinkit_india_po_summary_partner_biz where try_to_decimal(landing_rate,30,5) > 0 ) where rn = 1 ), po_avg as (select avg(lr) a from po_price), sales as ( select try_to_date(\"DATE\") as day, trim(item_id) as sku, initcap(lower(city_name)) as city, max(item_name) as product_name, max(category) as platform_category, sum(try_to_decimal(qty_sold,38,4)) as gross_units from vahdam_db.maplemonk.blinkit_india_sales_partner_biz where try_to_date(\"DATE\") is not null group by 1,2,3 ), lines as ( select s.day, s.sku, s.city, s.product_name, s.platform_category, coalesce(m.brand,\'Vahdam\') as brand, m.common_sku_id, m.common_sku_description, coalesce(m.category,\'Unmapped\') as category, coalesce(m.sub_category,\'Unmapped\') as sub_category, s.gross_units, s.gross_units * coalesce(pp.lr, pa.a) as net_sales_inr, coalesce(pp.lr, pa.a) as po_unit_price, case when pp.lr is not null then \'SKU\' else \'CHANNEL_AVG\' end as po_price_source, cast(0 as decimal(30,5)) as discount_inr, cg.cogs_per_unit_inr, case when cg.cogs_per_unit_inr is not null then \'N\' else \'Y\' end as cogs_fallback from sales s left join prod_map m on m.item_id = s.sku left join cogs_sheet cg on cg.common_sku_id = m.common_sku_id left join po_price pp on pp.item_id = s.sku cross join po_avg pa ), ad_day as ( select try_to_date(\"DATE\",\'DD-MM-YYYY\') as day, sum(try_to_decimal(replace(\"Estimated Budget Consumed\",\',\',\'\'),30,5)) as spend, sum(try_to_decimal(impressions,38,4)) as impressions, cast(null as decimal(38,4)) as clicks, sum(coalesce(try_to_decimal(replace(\"Direct Sales\",\',\',\'\'),30,5),0) +coalesce(try_to_decimal(replace(\"Indirect Sales\",\',\',\'\'),30,5),0)) as ads_revenue_inr from vahdam_db.maplemonk.blinkit_india_ads_ads where try_to_date(\"DATE\",\'DD-MM-YYYY\') is not null group by 1 ), sales_day as (select day, sum(net_sales_inr) as d_ns from lines group by 1), base as ( select l.day, l.sku, l.city, l.product_name, l.platform_category, l.brand, l.common_sku_id, l.common_sku_description, l.category, l.sub_category, l.gross_units, l.net_sales_inr, l.po_unit_price, l.po_price_source, l.discount_inr, l.cogs_per_unit_inr, l.cogs_fallback, coalesce(a.spend,0) * div0(l.net_sales_inr, sd.d_ns) as pm_spend_actual_inr, coalesce(a.impressions,0) * div0(l.net_sales_inr, sd.d_ns) as ads_impressions, coalesce(a.clicks,0) * div0(l.net_sales_inr, sd.d_ns) as ads_clicks, coalesce(a.ads_revenue_inr,0)* div0(l.net_sales_inr, sd.d_ns) as ads_revenue_inr from lines l join sales_day sd on sd.day = l.day left join ad_day a on a.day = l.day union all select a.day, \'__UNALLOCATED_ADS__\', cast(null as varchar), \'Unallocated ad spend (no sell-out that day)\', cast(null as varchar), \'Vahdam\', cast(null as varchar), cast(null as varchar), \'Unmapped\', \'Unmapped\', cast(0 as decimal(38,4)), cast(0 as decimal(38,4)), cast(null as decimal(30,5)), \'CHANNEL_AVG\', cast(0 as decimal(30,5)), cast(null as decimal(30,5)), \'Y\', a.spend, a.impressions, a.clicks, a.ads_revenue_inr from ad_day a left join sales_day sd on sd.day = a.day where coalesce(sd.d_ns,0) = 0 and coalesce(a.spend,0) > 0 ) select day, \'Blinkit\' as channel, \'IN\' as geo, \'INR\' as currency, 1 as fx_inr, sku, common_sku_id, common_sku_description, category, sub_category, city, product_name, platform_category, gross_units, net_sales_inr, po_unit_price as po_unit_price_inr_used, discount_inr, cogs_per_unit_inr as cogs_per_unit_inr_used, gross_units * coalesce(cogs_per_unit_inr,0) as cogs_actual_inr, 0.05 * net_sales_inr as last_mile_actual_inr, ( net_sales_inr - discount_inr - gross_units * coalesce(cogs_per_unit_inr,0) - 0.05 * net_sales_inr ) as cm1_actual_inr, ads_impressions, ads_clicks, ads_revenue_inr, pm_spend_actual_inr, ( net_sales_inr - discount_inr - gross_units * coalesce(cogs_per_unit_inr,0) - 0.05 * net_sales_inr - pm_spend_actual_inr ) as cm2_actual_inr, cogs_fallback, po_price_source from base ); CREATE OR REPLACE TABLE vahdam_db.maplemonk.vahdam_flipkart_pnl_unified AS ( WITH fk_map AS ( SELECT TRIM(REPLACE(FLIPKART,\'\"\',\'\')) AS fsn, ANY_VALUE(BRAND) AS brand, ANY_VALUE(\"Common SKU ID\") AS common_sku_id, ANY_VALUE(\"Common SKU Description\") AS common_sku_description, ANY_VALUE(CATEGORY) AS category, ANY_VALUE(\"Sub-category\") AS sub_category FROM vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_PRODUCT_MAPPING WHERE FLIPKART IS NOT NULL AND TRIM(REPLACE(FLIPKART,\'\"\',\'\')) NOT IN (\'\',\'-\') GROUP BY 1 ), cogs_sheet AS ( SELECT TRIM(MATERIAL) AS common_sku_id, AVG(TRY_TO_DECIMAL(REPLACE(COGS,\',\',\'\'),30,5)) AS cogs_per_unit_inr FROM vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_COGS_SHEET WHERE MATERIAL IS NOT NULL GROUP BY 1 ), earn_more AS ( SELECT TRY_TO_DATE(\"Order Date\") AS day, TRIM(REPLACE(\"SKU ID\",\'\"\',\'\')) AS sku, MAX(TRIM(REPLACE(\"Product Id\",\'\"\',\'\'))) AS fsn, MAX(TRIM(REPLACE(CATEGORY,\'\"\',\'\'))) AS fk_platform_category, SUM(TRY_TO_NUMBER(\"Gross Units\")) AS gross_units, SUM(TRY_TO_DECIMAL(REPLACE(GMV,\',\',\'\'),30,5)) AS gross_revenue_inr, SUM(TRY_TO_NUMBER(\"Return Units\")) AS return_units, SUM(TRY_TO_DECIMAL(REPLACE(\"Return Amount\",\',\',\'\'),30,5)) AS return_amount_inr, SUM(TRY_TO_NUMBER(\"Cancellation Units\")) AS cancellation_units, SUM(TRY_TO_DECIMAL(REPLACE(\"Cancellation Amount\",\',\',\'\'),30,5)) AS cancellation_amount_inr, SUM(TRY_TO_NUMBER(\"Final Sale Units\")) AS net_units, SUM(TRY_TO_DECIMAL(REPLACE(\"Final Sale Amount\",\',\',\'\'),30,5)) AS net_revenue_inr FROM (SELECT * FROM vahdam_db.maplemonk.FLIPKART_INDIA_EARN_MORE_REPORT QUALIFY ROW_NUMBER() OVER (PARTITION BY _AIRBYTE_UNIQUE_KEY ORDER BY _AIRBYTE_EMITTED_AT DESC)=1) WHERE TRY_TO_DATE(\"Order Date\") IS NOT NULL GROUP BY 1,2 ), sku_fsn_bridge AS ( SELECT sku, fsn FROM ( SELECT sku, fsn, ROW_NUMBER() OVER (PARTITION BY sku ORDER BY src_pri) rn FROM ( SELECT DISTINCT sku, fsn, 1 AS src_pri FROM earn_more UNION SELECT DISTINCT TRIM(REPLACE(REPLACE(SKU,\'\"\',\'\'),\'SKU:\',\'\')), TRIM(REPLACE(FSN,\'\"\',\'\')), 2 FROM vahdam_db.maplemonk.FLIPKART_INDIA_SALES UNION SELECT DISTINCT TRIM(REPLACE(REPLACE(SKU,\'\"\',\'\'),\'SKU:\',\'\')), TRIM(REPLACE(FSN,\'\"\',\'\')), 3 FROM vahdam_db.maplemonk.FLIPKART_INDIA_ORDERS ) WHERE sku IS NOT NULL AND sku NOT IN (\'\',\'-\') AND fsn IS NOT NULL AND fsn NOT IN (\'\',\'-\') ) WHERE rn = 1 ), sett AS ( SELECT TRIM(REPLACE(od.\"Seller SKU\",\'\"\',\'\')) AS sku, SUM(TRY_TO_NUMBER(od.QUANTITY)) AS qty, SUM(TRY_TO_DECIMAL(ts.\"Sale Amount (Rs.)\",30,5)) AS sale_amt, SUM(TRY_TO_DECIMAL(ts.\"My share (Rs.)\",30,5)) AS my_share, SUM(TRY_TO_DECIMAL(ts.\"Marketplace Fee (Rs.) = SUM (V:AI)\",30,5)) AS mp_fee, SUM(TRY_TO_DECIMAL(mf.\"Commission (Rs.)\",30,5)) AS commission FROM (SELECT * FROM vahdam_db.maplemonk.FLIPKART_INDIA_SETTLED_TRANSACTIONS_TRANSACTION_SUMMARY QUALIFY ROW_NUMBER() OVER (PARTITION BY _AIRBYTE_FLIPKART_INDIA_SETTLED_TRANSACTIONS_HASHID ORDER BY _AIRBYTE_EMITTED_AT DESC)=1) ts JOIN (SELECT * FROM vahdam_db.maplemonk.FLIPKART_INDIA_SETTLED_TRANSACTIONS_ORDER_DETAILS QUALIFY ROW_NUMBER() OVER (PARTITION BY _AIRBYTE_FLIPKART_INDIA_SETTLED_TRANSACTIONS_HASHID ORDER BY _AIRBYTE_EMITTED_AT DESC)=1) od ON od._AIRBYTE_FLIPKART_INDIA_SETTLED_TRANSACTIONS_HASHID = ts._AIRBYTE_FLIPKART_INDIA_SETTLED_TRANSACTIONS_HASHID LEFT JOIN (SELECT * FROM vahdam_db.maplemonk.FLIPKART_INDIA_SETTLED_TRANSACTIONS_MARKETPLACE_FEES QUALIFY ROW_NUMBER() OVER (PARTITION BY _AIRBYTE_FLIPKART_INDIA_SETTLED_TRANSACTIONS_HASHID ORDER BY _AIRBYTE_EMITTED_AT DESC)=1) mf ON mf._AIRBYTE_FLIPKART_INDIA_SETTLED_TRANSACTIONS_HASHID = ts._AIRBYTE_FLIPKART_INDIA_SETTLED_TRANSACTIONS_HASHID GROUP BY 1 ), sett_rates_sku AS ( SELECT sku, DIV0(-commission, NULLIF(sale_amt,0)) AS commission_pct, DIV0(-(mp_fee - commission), NULLIF(qty,0)) AS other_fees_per_unit, DIV0(-my_share, NULLIF(sale_amt,0)) AS offer_pct FROM sett WHERE sale_amt > 0 ), sett_rates_cat AS ( SELECT m.category, DIV0(-SUM(s.commission), NULLIF(SUM(s.sale_amt),0)) AS commission_pct, DIV0(-SUM(s.mp_fee - s.commission), NULLIF(SUM(s.qty),0)) AS other_fees_per_unit, DIV0(-SUM(s.my_share), NULLIF(SUM(s.sale_amt),0)) AS offer_pct FROM sett s JOIN sku_fsn_bridge b ON b.sku = s.sku JOIN fk_map m ON m.fsn = b.fsn WHERE s.sale_amt > 0 GROUP BY 1 ), sett_rates_all AS ( SELECT DIV0(-SUM(commission), NULLIF(SUM(sale_amt),0)) AS commission_pct, DIV0(-SUM(mp_fee - commission), NULLIF(SUM(qty),0)) AS other_fees_per_unit, DIV0(-SUM(my_share), NULLIF(SUM(sale_amt),0)) AS offer_pct FROM sett WHERE sale_amt > 0 ), ads_fsn AS ( SELECT TRY_TO_DATE(START_TIME) AS day, TRIM(REPLACE(\"Campaign ID\",\'\"\',\'\')) AS campaign_id, COALESCE(NULLIF(TRIM(REPLACE(\"Sku Id\",\'\"\',\'\')),\'\'),\'UNKNOWN\') AS sku, SUM(TRY_TO_NUMBER(CLICKS)) AS clicks, SUM(TRY_TO_NUMBER(VIEWS)) AS views, SUM(TRY_TO_DECIMAL(REPLACE(\"Total Revenue (Rs.)\",\',\',\'\'),30,5)) AS ads_revenue_inr, SUM(TRY_TO_NUMBER(\"Direct Units Sold\")) AS ads_direct_units, SUM(TRY_TO_NUMBER(\"Indirect Units Sold\")) AS ads_indirect_units FROM vahdam_db.maplemonk.FLIPKART_INDIA_ADS_SELLER_PORTAL_CONSOLIDATED_FSN_PLA WHERE TRY_TO_DATE(START_TIME) IS NOT NULL GROUP BY 1,2,3 ), pla_spend AS ( SELECT TRY_TO_DATE(START_TIME) AS day, TRIM(REPLACE(\"Campaign ID\",\'\"\',\'\')) AS campaign_id, SUM(TRY_TO_DECIMAL(REPLACE(\"Ad Spend\",\',\',\'\'),30,5)) AS spend FROM vahdam_db.maplemonk.FLIPKART_INDIA_ADS_SELLER_PORTAL_PLA WHERE TRY_TO_DATE(START_TIME) IS NOT NULL GROUP BY 1,2 ), camp_tot AS ( SELECT day, campaign_id, SUM(clicks) AS tot_clicks, SUM(views) AS tot_views, COUNT(*) AS n_skus FROM ads_fsn GROUP BY 1,2 ), ads_alloc AS ( SELECT f.day, f.sku, SUM(f.clicks) AS ads_clicks, SUM(f.views) AS ads_views, SUM(f.ads_revenue_inr) AS ads_revenue_inr, SUM(f.ads_direct_units) AS ads_direct_units, SUM(f.ads_indirect_units) AS ads_indirect_units, SUM(COALESCE(p.spend,0) * CASE WHEN c.tot_clicks > 0 THEN DIV0(f.clicks, c.tot_clicks) WHEN c.tot_views > 0 THEN DIV0(f.views, c.tot_views) ELSE 1 / NULLIF(c.n_skus,0) END) AS pm_spend_inr FROM ads_fsn f JOIN camp_tot c ON c.day = f.day AND c.campaign_id = f.campaign_id LEFT JOIN pla_spend p ON p.day = f.day AND p.campaign_id = f.campaign_id GROUP BY 1,2 ), universe AS ( SELECT day, sku FROM earn_more UNION SELECT day, sku FROM ads_alloc ), final AS ( SELECT u.day, \'Flipkart_3P\' AS channel, \'IN\' AS geo, \'INR\' AS currency, 1 AS fx_inr, u.sku, COALESCE(em.fsn, b.fsn) AS fsn, COALESCE(m.brand,\'Vahdam\') AS brand, m.common_sku_id, m.common_sku_description, COALESCE(m.category,\'Unmapped\') AS category, COALESCE(m.sub_category,\'Unmapped\') AS sub_category, em.fk_platform_category, COALESCE(em.gross_units,0) AS gross_units, COALESCE(em.gross_revenue_inr,0) AS gross_revenue_inr, COALESCE(em.return_units,0) AS return_units, COALESCE(em.return_amount_inr,0) AS return_amount_inr, COALESCE(em.cancellation_units,0) AS cancellation_units, COALESCE(em.cancellation_amount_inr,0) AS cancellation_amount_inr, COALESCE(em.net_units,0) AS net_units, COALESCE(em.net_revenue_inr,0) AS net_revenue_inr, cg.cogs_per_unit_inr AS cogs_per_unit_inr_used, COALESCE(rs.commission_pct, rc.commission_pct, ra.commission_pct, 0) AS commission_pct_used, COALESCE(rs.other_fees_per_unit, rc.other_fees_per_unit, ra.other_fees_per_unit, 0) AS other_fees_per_unit_used, COALESCE(rs.offer_pct, rc.offer_pct, ra.offer_pct, 0) AS offer_pct_used, CASE WHEN cg.cogs_per_unit_inr IS NOT NULL THEN \'N\' ELSE \'Y\' END AS cogs_fallback, CASE WHEN rs.sku IS NOT NULL THEN \'SKU\' WHEN rc.category IS NOT NULL THEN \'CATEGORY\' ELSE \'OVERALL\' END AS fee_rate_source, COALESCE(ad.ads_clicks,0) AS ads_clicks, COALESCE(ad.ads_views,0) AS ads_views, COALESCE(ad.ads_revenue_inr,0) AS ads_revenue_inr, COALESCE(ad.ads_direct_units,0) AS ads_direct_units, COALESCE(ad.ads_indirect_units,0) AS ads_indirect_units, COALESCE(ad.pm_spend_inr,0) AS pm_spend_actual_inr FROM universe u LEFT JOIN earn_more em ON em.day = u.day AND em.sku = u.sku LEFT JOIN ads_alloc ad ON ad.day = u.day AND ad.sku = u.sku LEFT JOIN sku_fsn_bridge b ON b.sku = u.sku LEFT JOIN fk_map m ON m.fsn = COALESCE(em.fsn, b.fsn) LEFT JOIN cogs_sheet cg ON cg.common_sku_id = m.common_sku_id LEFT JOIN sett_rates_sku rs ON rs.sku = u.sku LEFT JOIN sett_rates_cat rc ON rc.category = m.category CROSS JOIN sett_rates_all ra ) SELECT day, channel, geo, currency, fx_inr, sku, fsn, brand, common_sku_id, common_sku_description, category, sub_category, fk_platform_category, gross_units, gross_revenue_inr, return_units, return_amount_inr, cancellation_units, cancellation_amount_inr, net_units, net_revenue_inr, cogs_per_unit_inr_used, net_units * COALESCE(cogs_per_unit_inr_used,0) AS cogs_actual_inr, net_revenue_inr * commission_pct_used AS commission_actual_inr, net_units * other_fees_per_unit_used AS fixed_other_fees_actual_inr, net_revenue_inr * offer_pct_used AS offer_funding_actual_inr, net_units * 0 AS last_mile_actual_inr, net_revenue_inr - net_units * COALESCE(cogs_per_unit_inr_used,0) - net_revenue_inr * commission_pct_used - net_units * other_fees_per_unit_used - net_revenue_inr * offer_pct_used AS cm1_actual_inr, ads_clicks, ads_views, ads_revenue_inr, ads_direct_units, ads_indirect_units, pm_spend_actual_inr, net_revenue_inr - net_units * COALESCE(cogs_per_unit_inr_used,0) - net_revenue_inr * commission_pct_used - net_units * other_fees_per_unit_used - net_revenue_inr * offer_pct_used - pm_spend_actual_inr AS cm2_actual_inr, cogs_fallback, fee_rate_source FROM final ); create or replace table vahdam_db.maplemonk.vahdam_swiggy_pnl_unified as ( with prod_map as ( select trim(replace(swiggy,\'\"\',\'\')) as item_code, any_value(brand) as brand, any_value(trim(\"Common SKU ID\")) as common_sku_id, any_value(\"Common SKU Description\") as common_sku_description, any_value(category) as category, any_value(\"Sub-category\") as sub_category from vahdam_db.maplemonk.vahdam_fy27_inputs_product_mapping where swiggy is not null and trim(replace(swiggy,\'\"\',\'\')) not in (\'\',\'-\') group by 1 ), cogs_sheet as ( select trim(material) as common_sku_id, avg(try_to_decimal(replace(cogs,\',\',\'\'),30,5)) as cogs_per_unit_inr from vahdam_db.maplemonk.vahdam_fy27_inputs_cogs_sheet where material is not null and try_to_decimal(replace(cogs,\',\',\'\'),30,5) > 0 group by 1 ), po_price as ( select skucode, lr from ( select trim(skucode) skucode, try_to_decimal(unitbasedcost,30,5) lr, row_number() over (partition by trim(skucode) order by try_to_date(left(pocreatedat,10)) desc nulls last) rn from vahdam_db.maplemonk.swiggy_india_purchase_orders where try_to_decimal(unitbasedcost,30,5) > 0 ) where rn = 1 ), po_avg as (select avg(lr) a from po_price), disc as ( select try_to_date(left(order_date,10)) as day, trim(to_varchar(cast(item_code as integer))) as sku, sum(cast(discount_spend as decimal(30,5))) as discount_inr from vahdam_db.maplemonk.swiggy_brand_funded_discounts where try_to_date(left(order_date,10)) is not null and item_code is not null group by 1,2 ), sales as ( select try_to_date(left(ordered_date,10)) as day, trim(item_code) as sku, initcap(lower(city)) as city, max(product_name) as product_name, max(l2_category) as platform_category, sum(try_to_decimal(units_sold,38,4)) as gross_units from vahdam_db.maplemonk.swiggy_india_sales where try_to_date(left(ordered_date,10)) is not null group by 1,2,3 ), lines0 as ( select s.day, s.sku, s.city, s.product_name, s.platform_category, coalesce(m.brand,\'Vahdam\') as brand, m.common_sku_id, m.common_sku_description, coalesce(m.category,\'Unmapped\') as category, coalesce(m.sub_category,\'Unmapped\') as sub_category, s.gross_units, s.gross_units * coalesce(pp.lr, pa.a) as net_sales_inr, coalesce(pp.lr, pa.a) as po_unit_price, case when pp.lr is not null then \'SKU\' else \'CHANNEL_AVG\' end as po_price_source, cg.cogs_per_unit_inr, case when cg.cogs_per_unit_inr is not null then \'N\' else \'Y\' end as cogs_fallback from sales s left join prod_map m on m.item_code = s.sku left join cogs_sheet cg on cg.common_sku_id = m.common_sku_id left join po_price pp on pp.skucode = s.sku cross join po_avg pa ), sku_day as (select day, sku, sum(net_sales_inr) as ns from lines0 group by 1,2), lines as ( select l.day, l.sku, l.city, l.product_name, l.platform_category, l.brand, l.common_sku_id, l.common_sku_description, l.category, l.sub_category, l.gross_units, l.net_sales_inr, l.po_unit_price, l.po_price_source, coalesce(d.discount_inr,0) * div0(l.net_sales_inr, sk.ns) as discount_inr, l.cogs_per_unit_inr, l.cogs_fallback from lines0 l left join sku_day sk on sk.day = l.day and sk.sku = l.sku left join disc d on d.day = l.day and d.sku = l.sku ), ad_day as ( select try_to_date(left(metrics_date,10)) as day, sum(try_to_decimal(total_budget_burnt,30,5)) as spend, sum(try_to_decimal(total_impressions,38,4)) as impressions, sum(try_to_decimal(total_clicks,38,4)) as clicks, sum(try_to_decimal(total_gmv,30,5)) as ads_revenue_inr from vahdam_db.maplemonk.swiggy_granular_reports where try_to_date(left(metrics_date,10)) is not null group by 1 ), sales_day as (select day, sum(net_sales_inr) as d_ns from lines0 group by 1), base as ( select l.day, l.sku, l.city, l.product_name, l.platform_category, l.brand, l.common_sku_id, l.common_sku_description, l.category, l.sub_category, l.gross_units, l.net_sales_inr, l.po_unit_price, l.po_price_source, l.discount_inr, l.cogs_per_unit_inr, l.cogs_fallback, coalesce(a.spend,0) * div0(l.net_sales_inr, sd.d_ns) as pm_spend_actual_inr, coalesce(a.impressions,0) * div0(l.net_sales_inr, sd.d_ns) as ads_impressions, coalesce(a.clicks,0) * div0(l.net_sales_inr, sd.d_ns) as ads_clicks, coalesce(a.ads_revenue_inr,0)* div0(l.net_sales_inr, sd.d_ns) as ads_revenue_inr from lines l join sales_day sd on sd.day = l.day left join ad_day a on a.day = l.day union all select a.day, \'__UNALLOCATED_ADS__\', cast(null as varchar), \'Unallocated ad spend (no sell-out that day)\', cast(null as varchar), \'Vahdam\', cast(null as varchar), cast(null as varchar), \'Unmapped\', \'Unmapped\', cast(0 as decimal(38,4)), cast(0 as decimal(38,4)), cast(null as decimal(30,5)), \'CHANNEL_AVG\', cast(0 as decimal(30,5)), cast(null as decimal(30,5)), \'Y\', a.spend, a.impressions, a.clicks, a.ads_revenue_inr from ad_day a left join sales_day sd on sd.day = a.day where coalesce(sd.d_ns,0) = 0 and coalesce(a.spend,0) > 0 ) select day, \'Swiggy Instamart\' as channel, \'IN\' as geo, \'INR\' as currency, 1 as fx_inr, sku, common_sku_id, common_sku_description, category, sub_category, city, product_name, platform_category, gross_units, net_sales_inr, po_unit_price as po_unit_price_inr_used, discount_inr, cogs_per_unit_inr as cogs_per_unit_inr_used, gross_units * coalesce(cogs_per_unit_inr,0) as cogs_actual_inr, 0.05 * net_sales_inr as last_mile_actual_inr, ( net_sales_inr - discount_inr - gross_units * coalesce(cogs_per_unit_inr,0) - 0.05 * net_sales_inr ) as cm1_actual_inr, ads_impressions, ads_clicks, ads_revenue_inr, pm_spend_actual_inr, ( net_sales_inr - discount_inr -